class Solution {
public:
    int getMaxLen(vector<int>& nums) {
        int n = nums.size();
        int ans = 0;
        int i = 0;
        while (i < n) {
            while (i < n && nums[i] == 0) i++;
            int start = i;
            int firstNeg = -1, lastNeg = -1, negCount = 0;
            while (i < n && nums[i] != 0) {
                if (nums[i] < 0) {
                    if (firstNeg == -1) firstNeg = i;
                    lastNeg = i;
                    negCount++;
                }
                i++;
            }
            int end = i;
            if (negCount % 2 == 0) {
                ans = max(ans, end - start);
            } else {
                ans = max(ans, end - (firstNeg + 1));
                ans = max(ans, lastNeg - start);
            }
        }
        return ans;
    }
};
